//! demo.py cross-validation: the Helion BitLocator must agree with the
//! reference BitFiltrator demo.py run on the synthetic xcku3p bitstream.
//!
//! The expected values come from `scripts/synth_xcku3p_expected.json`,
//! generated by `scripts/make_synth_xcku3p_bit.py` from the reference
//! BitLocator and verified against demo.py output (see
//! `scripts/demo_validation.md`). If this test fails, either the loader
//! or the reference data changed; re-run the generator script and diff
//! the JSON before touching the loader. The generator re-verifies the
//! demo.py output on every run, so a changed JSON means the reference
//! itself moved, not just this test.

use helion_ultrascale::{ArchSummary, BitLocator, DeviceFile};
use serde_json::Value;
use std::collections::BTreeSet;
use std::path::PathBuf;

fn manifest_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn expected() -> Value {
    let text = std::fs::read_to_string(manifest_dir().join("scripts/synth_xcku3p_expected.json"))
        .expect("golden JSON from make_synth_xcku3p_bit.py");
    serde_json::from_str(&text).expect("golden JSON parses")
}

fn locator() -> (DeviceFile, ArchSummary) {
    let data = manifest_dir().join("data");
    let device = DeviceFile::from_path(&data.join("xcku3p.json")).unwrap();
    let arch = ArchSummary::from_path(&data.join("ULTRASCALE_PLUS.json")).unwrap();
    (device, arch)
}

/// FNV-1a 64 over the canonical "far_hex:ofst;" serialization, the
/// same digest the generator script computes in Python.
fn fnv1a64(pairs: &[(String, u32)]) -> String {
    let mut h: u64 = 0xcbf2_9ce4_8422_2325;
    for (far_hex, ofst) in pairs {
        for b in format!("{far_hex}:{ofst};").bytes() {
            h ^= u64::from(b);
            h = h.wrapping_mul(0x0000_0100_0000_01b3);
        }
    }
    format!("{h:016x}")
}

fn pairs_of(arr: &Value) -> Vec<(String, u32)> {
    arr.as_array()
        .expect("pairs is an array")
        .iter()
        .map(|p| {
            (
                p[0].as_str().expect("far hex").to_string(),
                p[1].as_u64().expect("offset") as u32,
            )
        })
        .collect()
}

#[test]
fn demo_lut_matches_reference() {
    let exp = expected();
    let bel = &exp["bels"]["SLICE_X23Y45/B6LUT"];
    let want = pairs_of(&bel["pairs"]);
    let (device, arch) = locator();
    let loc = BitLocator::new(&device, &arch);
    let (slr, fars, ofsts) = loc.locate_lut("SLICE_X23Y45/B6LUT").unwrap();
    assert_eq!(slr, bel["slr"].as_str().unwrap());
    assert_eq!(fars.len(), 64);
    let got: Vec<(String, u32)> = fars
        .iter()
        .zip(ofsts.iter())
        .map(|(f, o)| (f.to_hex(), *o))
        .collect();
    assert_eq!(got, want);
}

#[test]
fn demo_ff_matches_reference() {
    let exp = expected();
    let bel = &exp["bels"]["SLICE_X23Y45/BFF"];
    let want = pairs_of(&bel["pairs"]);
    assert_eq!(want.len(), 1);
    let (device, arch) = locator();
    let loc = BitLocator::new(&device, &arch);
    let (slr, far, ofst) = loc.locate_reg("SLICE_X23Y45/BFF").unwrap();
    assert_eq!(slr, bel["slr"].as_str().unwrap());
    assert_eq!(vec![(far.to_hex(), ofst)], want);
}

#[test]
fn demo_bram_matches_reference() {
    let exp = expected();
    let bel = &exp["bels"]["RAMB18_X0Y0"];
    let (device, arch) = locator();
    let loc = BitLocator::new(&device, &arch);
    let (slr, mem_fars, mem_ofsts, par_fars, par_ofsts) = loc.locate_bram("RAMB18_X0Y0").unwrap();
    assert_eq!(slr, bel["slr"].as_str().unwrap());

    let mem: Vec<(String, u32)> = mem_fars
        .iter()
        .zip(mem_ofsts.iter())
        .map(|(f, o)| (f.to_hex(), *o))
        .collect();
    let par: Vec<(String, u32)> = par_fars
        .iter()
        .zip(par_ofsts.iter())
        .map(|(f, o)| (f.to_hex(), *o))
        .collect();
    assert_eq!(mem.len(), 16384);
    assert_eq!(par.len(), 2048);

    // Distinct FAR sets (every frame the BRAM touches).
    let mem_set: BTreeSet<String> = mem.iter().map(|(f, _)| f.clone()).collect();
    let par_set: BTreeSet<String> = par.iter().map(|(f, _)| f.clone()).collect();
    let want_mem: BTreeSet<String> = bel["content_distinct_fars"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let want_par: BTreeSet<String> = bel["parity_distinct_fars"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    assert_eq!(mem_set, want_mem);
    assert_eq!(par_set, want_par);

    // First 8 pairs in order, plus a digest of the full ordered lists.
    let want_mem8 = pairs_of(&bel["content_first8"]);
    let want_par8 = pairs_of(&bel["parity_first8"]);
    assert_eq!(&mem[..8], want_mem8.as_slice());
    assert_eq!(&par[..8], want_par8.as_slice());
    assert_eq!(
        fnv1a64(&mem),
        bel["content_fnv1a64"].as_str().unwrap(),
        "content full-list digest"
    );
    assert_eq!(
        fnv1a64(&par),
        bel["parity_fnv1a64"].as_str().unwrap(),
        "parity full-list digest"
    );
}
